import React, { useState, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId]       = useState("");
  const [qrData, setQrData]       = useState("");
  const [photo, setPhoto]         = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [utrNumber, setUtrNumber] = useState("");
  const [verifying, setVerifying] = useState(false);

  const videoRef  = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* ── Your UPI details ──────────────────────────────── */
  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT      = "1";
  const PAYEE_NAME  = "CollegeEvent";
  /* ─────────────────────────────────────────────────── */

  const isAndroid = /Android/i.test(navigator.userAgent);
  const isIOS     = /iPhone|iPad|iPod/i.test(navigator.userAgent);
  const isMobile  = isAndroid || isIOS;

  const encodedName = encodeURIComponent(PAYEE_NAME);
  const encodedNote = encodeURIComponent("EventRegistration");
  const upiBase     = `pa=${YOUR_UPI_ID}&pn=${encodedName}&am=${AMOUNT}&cu=INR&tn=${encodedNote}`;

  /* =============================
     UPI PAYMENT OPENER
  ============================= */
  const openUPIApp = (app) => {
    if (isAndroid) {
      /* Android → intent:// scheme forces the specific installed app */
      const intentMap = {
        gpay:    `intent://pay?${upiBase}#Intent;scheme=tez;package=com.google.android.apps.nbu.paisa.user;end`,
        phonepe: `intent://pay?${upiBase}#Intent;scheme=phonepe;package=com.phonepe.app;end`,
        paytm:   `intent://pay?${upiBase}#Intent;scheme=paytmmp;package=net.one97.paytm;end`,
        any:     `upi://pay?${upiBase}`,
      };
      window.location.href = intentMap[app];

    } else if (isIOS) {
      /* iOS → custom URL scheme */
      const iosMap = {
        gpay:    `tez://upi/pay?${upiBase}`,
        phonepe: `phonepe://pay?${upiBase}`,
        paytm:   `paytmmp://pay?${upiBase}`,
        any:     `upi://pay?${upiBase}`,
      };
      window.location.href = iosMap[app];

    } else {
      /* Desktop → open the official website in a new tab.
         User can login there and pay via UPI ID or scan QR. */
      const webMap = {
        gpay:    `https://pay.google.com/`,
        phonepe: `https://web.phonepe.com/`,
        paytm:   `https://paytm.com/`,
        any:     `https://pay.google.com/`,
      };
      window.open(webMap[app], "_blank");
    }
  };

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     SHOW PAYMENT SCREEN
  ============================= */
  const handleShowPayment = (e) => {
    e.preventDefault();
    setShowPayment(true);
  };

  /* =============================
     VERIFY UTR + REGISTER
  ============================= */
  const verifyAndRegister = async () => {
    if (!utrNumber.trim()) {
      alert("Please enter your UTR / Transaction ID");
      return;
    }
    if (utrNumber.trim().length < 10) {
      alert("UTR must be at least 10 characters. Please check and try again.");
      return;
    }
    setVerifying(true);
    try {
      const res = await axios.post("http://localhost:5000/verify-utr", {
        utrNumber: utrNumber.trim(),
        amount: AMOUNT,
        ...formData,
        photo,
      });
      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        alert("Payment Verified! Registration Successful.");
      } else {
        alert(res.data.message || "UTR verification failed. Please try again.");
      }
    } catch {
      alert("Verification failed. Please contact support.");
    } finally {
      setVerifying(false);
    }
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width  = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    setPhoto(canvas.toDataURL("image/png"));
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  /* =============================
     INLINE SVG LOGOS (no broken img tags)
  ============================= */
  const GPayLogo = () => (
    <svg width="22" height="22" viewBox="0 0 48 48" fill="none">
      <text y="36" fontSize="36" fontFamily="Arial">G</text>
    </svg>
  );

  const PhonePeLogo = () => (
    <svg width="22" height="22" viewBox="0 0 48 48">
      <circle cx="24" cy="24" r="24" fill="#fff"/>
      <text x="10" y="33" fontSize="24" fontFamily="Arial" fill="#5f259f" fontWeight="bold">P</text>
    </svg>
  );

  const PaytmLogo = () => (
    <svg width="22" height="22" viewBox="0 0 48 48">
      <rect width="48" height="48" rx="6" fill="#fff"/>
      <text x="4" y="34" fontSize="18" fontFamily="Arial" fill="#00BAF2" fontWeight="bold">Pay</text>
    </svg>
  );

  /* =============================
     STYLES
  ============================= */
  const card = {
    background: "#fff",
    border: "1px solid #e5e7eb",
    borderRadius: "12px",
    padding: "16px",
    marginBottom: "16px",
  };

  const btnPay = (bg) => ({
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    gap: "10px",
    padding: "14px 20px",
    border: "none",
    borderRadius: "10px",
    fontSize: "15px",
    fontWeight: "bold",
    cursor: "pointer",
    width: "100%",
    backgroundColor: bg,
    color: "#fff",
    marginBottom: "10px",
    boxSizing: "border-box",
  });

  return (
    <div>
      <Navbar />

      <div style={{ textAlign: "center", padding: "20px" }}>
        <h2>Event Registration</h2>

        {/* ── STEP 1: FORM ── */}
        {!showPayment && !qrData && (
          <form onSubmit={handleShowPayment}>
            <input name="name" placeholder="Name" onChange={handleChange} required />
            <br /><br />
            <input name="college_name" placeholder="College Name" onChange={handleChange} required />
            <br /><br />
            <input name="phone" placeholder="Phone" onChange={handleChange} required />
            <br /><br />
            <input name="email" placeholder="Email" onChange={handleChange} required />
            <br /><br />
            <h3>Selected Event: {eventName}</h3>
            <button
              type="submit"
              style={{
                padding: "13px 36px",
                backgroundColor: "#4f46e5",
                color: "#fff",
                border: "none",
                borderRadius: "10px",
                fontSize: "16px",
                fontWeight: "bold",
                cursor: "pointer",
              }}
            >
              Proceed to Pay ₹{AMOUNT}
            </button>
          </form>
        )}

        {/* ── STEP 2: PAYMENT SCREEN ── */}
        {showPayment && !qrData && (
          <div style={{ maxWidth: "420px", margin: "auto", textAlign: "left" }}>
            <h3 style={{ textAlign: "center", marginBottom: "18px" }}>
              Pay ₹{AMOUNT} to Register
            </h3>

            {/* Desktop notice */}
            {!isMobile && (
              <div style={{
                background: "#fffbeb",
                border: "1px solid #fbbf24",
                borderRadius: "8px",
                padding: "10px 14px",
                marginBottom: "16px",
                fontSize: "13px",
                color: "#92400e",
              }}>
                <strong>On desktop?</strong> The buttons below will open the payment app's
                website. For direct app payment, open this page on your <strong>mobile phone</strong>,
                or scan the QR code below using GPay / PhonePe / Paytm.
              </div>
            )}

            {/* Payment Buttons */}
            <div style={card}>
              <p style={{ fontWeight: "600", marginBottom: "12px", fontSize: "14px" }}>
                Select payment app:
              </p>

              <button onClick={() => openUPIApp("gpay")} style={btnPay("#1a73e8")}>
                <GPayLogo />
                Pay with GPay
              </button>

              <button onClick={() => openUPIApp("phonepe")} style={btnPay("#5f259f")}>
                <PhonePeLogo />
                Pay with PhonePe
              </button>

              <button onClick={() => openUPIApp("paytm")} style={btnPay("#00a8e8")}>
                <PaytmLogo />
                Pay with Paytm
              </button>

              <button onClick={() => openUPIApp("any")} style={btnPay("#059669")}>
                Any Other UPI App
              </button>
            </div>

            {/* QR Code */}
            <div style={{ ...card, textAlign: "center" }}>
              <p style={{ fontSize: "13px", color: "#555", marginBottom: "12px", fontWeight: "600" }}>
                Or scan this QR with any UPI app:
              </p>
              <div style={{ display: "inline-block", padding: "10px", background: "#fff", borderRadius: "8px", border: "1px solid #e5e7eb" }}>
                <QRCode
                  value={`upi://pay?pa=${YOUR_UPI_ID}&pn=${encodedName}&am=${AMOUNT}&cu=INR`}
                  size={150}
                />
              </div>
              <p style={{ fontSize: "12px", color: "#6b7280", marginTop: "10px" }}>
                UPI ID: <strong>{YOUR_UPI_ID}</strong>
                &nbsp;&nbsp;|&nbsp;&nbsp;
                Amount: <strong>₹{AMOUNT}</strong>
              </p>
            </div>

            {/* UTR Input */}
            <div style={card}>
              <p style={{ fontWeight: "600", marginBottom: "4px", fontSize: "14px" }}>
                After paying, enter your UTR / Transaction ID:
              </p>
              <p style={{ fontSize: "12px", color: "#9ca3af", marginBottom: "12px" }}>
                GPay → UPI Ref. No. &nbsp;|&nbsp;
                PhonePe → Transaction ID &nbsp;|&nbsp;
                Paytm → UTR Number &nbsp;|&nbsp;
                Or check your bank SMS
              </p>

              <input
                type="text"
                placeholder="Enter UTR / Transaction ID"
                value={utrNumber}
                onChange={(e) =>
                  setUtrNumber(e.target.value.replace(/\s/g, "").slice(0, 22))
                }
                style={{
                  padding: "12px 14px",
                  fontSize: "15px",
                  width: "100%",
                  boxSizing: "border-box",
                  borderRadius: "8px",
                  border: "1px solid #d1d5db",
                  marginBottom: "12px",
                  letterSpacing: "1px",
                  outline: "none",
                }}
              />

              <button
                onClick={verifyAndRegister}
                disabled={verifying || utrNumber.trim().length < 10}
                style={{
                  ...btnPay(
                    verifying || utrNumber.trim().length < 10 ? "#9ca3af" : "#16a34a"
                  ),
                  cursor:
                    verifying || utrNumber.trim().length < 10
                      ? "not-allowed"
                      : "pointer",
                  marginBottom: 0,
                }}
              >
                {verifying ? "Verifying..." : "Verify & Get ID Card"}
              </button>
            </div>

            <button
              onClick={() => { setShowPayment(false); setUtrNumber(""); }}
              style={{
                background: "none",
                border: "none",
                color: "#6b7280",
                cursor: "pointer",
                textDecoration: "underline",
                fontSize: "13px",
                display: "block",
                margin: "0 auto 20px",
              }}
            >
              ← Back to Form
            </button>
          </div>
        )}

        {/* ── STEP 3: QR + CAMERA ── */}
        {qrData && (
          <div>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={200} />
            <br /><br />
            <button onClick={openCamera}>Open Camera</button>
            <br /><br />
            <video
              ref={videoRef}
              width="320"
              height="240"
              style={{ border: "2px solid black" }}
            />
            <br /><br />
            <button onClick={capturePhoto}>Capture Photo</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ── STEP 4: ID CARD ── */}
        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div
              ref={idCardRef}
              style={{
                border: "2px solid black",
                width: "300px",
                margin: "auto",
                padding: "15px",
                borderRadius: "10px",
              }}
            >
              <h3>College Event ID Card</h3>
              <p>Name : {formData.name}</p>
              <p>User ID : {userId}</p>
              <p>Event : {eventName}</p>
              <QRCode value={qrData.toString()} size={120} />
              <br /><br />
              <img src={photo} alt="User" width="120" />
            </div>
            <br />
            <button onClick={downloadCard}>Download ID Card</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
